"""중1 영어 진단 세트."""
from question_bank.elementary._common import make_question,validate_elementary_questions
L,S="중1","영어";K=[3,2,3,3,4,1,2,1,2,2,3,1,1,2,3];T=[35,35,35,35,30,35,35,40,35,45,50,50,40,45,45]
def q(n,a,s,t,o,c,ad=False):return make_question(f"M1ENG-{n:02d}",L,S,a,s,t,o,c,T[n-1],f"{o[c-1]}가 문법과 문맥에 맞습니다.",f"{s}를 다시 확인할 필요가 있음.",ad)
D=[("문장 기초","be동사 일치","They ___ students.",["am","is","are","be","was"],3),("문장 기초","일반동사 3인칭 단수","She ___ to school every day.",["go","goes","going","went","gone"],2),("시제·표현","현재진행형","Mina ___ a book now.",["read","reads","is reading","readed","has read"],3),("시제·표현","과거시제","Yesterday, I ___ to the museum.",["go","goes","went","going","gone"],3),("조동사","can 뒤 동사원형","He can ___ fast.",["runs","ran","running","run","to run"],4),("문장 구조","There are","___ three apples on the table.",["There are","There is","It is","They is","There be"],1),("비교 표현","비교급","An elephant is ___ than a dog.",["big","bigger","biggest","more big","the bigger"],2),("의미 이해","목적 표현","I went to the library to study. 도서관에 간 목적은?",["공부하기 위해","친구를 만나기 위해","잠자기 위해","운동하기 위해","음식을 사기 위해"],1),("접속 표현","because","I stayed home because it was raining. 집에 머문 까닭은?",["눈이 와서","비가 와서","더워서","친구가 와서","숙제가 없어서"],2),("읽기 이해","대명사 지시 대상","Tom bought a new bike. He rides it every day. ‘it’이 가리키는 것은?",["Tom","new bike","every day","friend","school"],2),("읽기 이해","세부 정보","Jina eats breakfast at 7:30 and leaves home at 8:00. 몇 시에 아침을 먹나요?",["7:00","7:15","7:30","8:00","8:30"],3),("읽기 이해","상황 추론","Dark clouds filled the sky. Mina took an umbrella before leaving home. 가장 자연스럽게 예상할 수 있는 것은?",["비가 올 수 있다.","눈이 반드시 온다.","날씨가 아주 덥다.","우산이 고장 났다.","Mina는 집에 남는다."],1),("어휘","문맥 어휘","borrow의 뜻으로 가장 알맞은 것은?",["빌리다","빌려주다","버리다","고치다","선택하다"],1),("다음 단계 진입 탐색","현재완료 개념 진입","I ___ here for three years.",["live","have lived","lived yesterday","am living now only","will live"],2,True),("다음 단계 진입 탐색","수동태 의미 진입","The cake was made by Mina. 케이크를 만든 사람은?",["Tom","Jisu","Mina","the cake","알 수 없음"],3,True)]
Q=[q(i+1,*x)for i,x in enumerate(D)];validate_elementary_questions(Q,K,500,90)
QUESTION_SET={"level":L,"subject":S,"curriculum":"2022 개정 교육과정 중학교 영어 참고","curriculum_year":2026,"test_version":"M1_ENG_2022R_2026_v1.0","core_count":13,"advance_count":2,"display_name":"중1 영어 진단","questions":Q}
